#!/usr/bin/env python3

import sys
import os
import re

from operator import attrgetter

cur_scr_dir = os.path.dirname(os.path.abspath(__file__))
pubfunc_dir = os.path.abspath(cur_scr_dir + "/../../public")
sys.path.append(pubfunc_dir)

from pubfunc import PubFunc

class CommonFiles:
    def __init__(self, env_gen):
        self.project_path = env_gen.project_path

    def __str__(self):
        str_info = ""
        str_info += "------ CommFiles Start ------\n"
        str_info += "project_path(%s)\n" % self.project_path
        str_info += "------ CommFiles End ------\n"
        return str_info

    def gen_common_checking_macro(self):
        os.system('cp -r %s/common_template/common_checking_macro.sv %s/common/' % (cur_scr_dir, self.project_path))

    def gen_common_define(self):
        file_name = "common_define.sv"
        file_path = "%s/common/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))
        content = '''
`ifndef COMMON_DEFINE__SV
`define COMMON_DEFINE__SV

import uvm_pkg::*;

`endif // COMMON_DEFINE__SV
'''
        file_handler.write(content)
        file_handler.close()

    def gen_hierarchy_define(self):
        file_name = "hierarchy_define.sv"
        file_path = "%s/common/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))
        content = '''
`ifndef HIERARCHY_DEFINE__SV
`define HIERARCHY_DEFINE__SV

`ifdef MIX_SIM
    // ANA_TOP mode, CHIP_TOP must match spice file: input.sp
    // `define ANA_TOP         top.u_ana
    // `define CHIP_TOP         top.u_ana.xi0.xdig_top
`else
    `define CHIP_TOP            top.u_chip_top
    // `define CHIP_RESETN         `CHIP_TOP.RST_N
`endif

// `define EMC_TOP             `CHIP_TOP.u_emc_dig_top
// `define IOMUX_TOP           `CHIP_TOP.u_iomux_top

// used for trans message between CCODE and sv
// `define TARGET_SRAM_TOP             `SRAM1_TOP
//
// `define TARGET_SRAM                 `TARGET_SRAM_TOP.mem
// `define TARGET_SRAM_CLK             `TARGET_SRAM_TOP.CLK
//
// `define BASE_MEM_INDEX_OF_PRINT     $size(`TARGET_SRAM) - 57
// `define INDEX_OF_END_SIM            `BASE_MEM_INDEX_OF_PRINT + 0
// `define INDEX_OF_OK_OR_ERROR        `BASE_MEM_INDEX_OF_PRINT + 1
// `define INDEX_OF_WAIT_LABEL         `BASE_MEM_INDEX_OF_PRINT + 2
// `define INDEX_OF_SEND_LABEL         `BASE_MEM_INDEX_OF_PRINT + 2
// `define INDEX_OF_INFO               `BASE_MEM_INDEX_OF_PRINT + 3
// `define INDEX_OF_FIRST_DATA         `BASE_MEM_INDEX_OF_PRINT + 4
// `define INDEX_OF_STRING_HEAD        `BASE_MEM_INDEX_OF_PRINT + 24
// `define INDEX_OF_STRING_INFO        `BASE_MEM_INDEX_OF_PRINT + 25



`endif // HIERARCHY_DEFINE__SV
'''
        file_handler.write(content)
        file_handler.close()

    def gen_memory_map(self):
        file_name = "memory_map.sv"
        file_path = "%s/common/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))
        content = '''
`ifndef MEMORY_MAP__SV
`define MEMORY_MAP__SV

`define LDROM_SADDR         'h0000_0000
`define LDROM_EADDR         'h0000_FFFF

`define APROM_SADDR         'h0008_0000
`define APROM_EADDR         'h000E_FFFF

`define SRAM1_SADDR         'h2000_0000
`define SRAM1_EADDR         'h2000_FFFF

`define SRAM2_SADDR         'h2001_0000
`define SRAM2_EADDR         'h2001_FFFF

`define SRAM3_SADDR         'h2002_0000
`define SRAM3_EADDR         'h2002_FFFF

`endif // MEMORY_MAP__SV
'''
        file_handler.write(content)
        file_handler.close()

    def gen_common_define_top(self):
        file_name = "common_define_top.sv"
        file_path = "%s/common/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))
        file_handler.write('`include "../common/common_define.sv"\n')
        file_handler.write('`include "../common/hierarchy_define.sv"\n')
        file_handler.write('`include "../common/memory_map.sv"\n')
        file_handler.write('`include "../common/common_checking_macro.sv"\n')
        file_handler.close()

    def gen_files(self):
        self.gen_common_define()
        self.gen_memory_map()
        self.gen_hierarchy_define()
        self.gen_common_define_top()
        self.gen_common_checking_macro();

#!/usr/bin/env python3

import sys
import os
import re

from operator import attrgetter

cur_scr_dir = os.path.dirname(os.path.abspath(__file__))
pubfunc_dir = os.path.abspath(cur_scr_dir + "/../../public")
sys.path.append(pubfunc_dir)

from pubfunc import PubFunc

class EnvFiles:
    def __init__(self, env_gen):
        self.project_name = env_gen.project_name
        self.project_path = env_gen.project_path
        self.mst_agent_list = env_gen.mst_agent_list
        self.slv_agent_list = env_gen.slv_agent_list
        self.refm_list = env_gen.refm_list
        self.scb_list = env_gen.scb_list
        self.cov_list = env_gen.cov_list

    def __str__(self):
        str_info = ""
        str_info += "------ EnvFiles Start ------\n"
        str_info += "project_name(%s)\n" % self.project_name
        str_info += "project_path(%s)\n" % self.project_path
        str_info += "------ EnvFiles End ------\n"
        return str_info

    def gen_env(self):
        member_type_list = []
        member_name_list = []
        aligned_member_type_list = []
        file_name = "env.sv"
        file_path = "%s/env/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))

        # virtual_seqr
        member_type_list.append("vir_seqr")
        member_name_list.append("mo_vir_seqr")
        # RAL
        member_type_list.append("ral_regmodel")
        member_name_list.append("mo_regmodel")
        # env_cfg
        member_type_list.append("env_cfg")
        member_name_list.append("mo_env_cfg")

        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip:
                continue
            member_type_list.append("%s_agent" % cur_agent.name)
            if cur_agent.count == 1:
                member_name_list.append("mo_%s_master_agent" % cur_agent.name)
            else:
                member_name_list.append("moa_%s_master_agent[%s]" % (cur_agent.name, cur_agent.count))
        for cur_agent in self.slv_agent_list:
            if cur_agent.is_vip:
                continue
            member_type_list.append("%s_agent" % cur_agent.name)
            if cur_agent.count == 1:
                member_name_list.append("mo_%s_slaver_agent" % cur_agent.name)
            else:
                member_name_list.append("moa_%s_slaver_agent[%s]" % (cur_agent.name, cur_agent.count))
        for cur_refm in self.refm_list:
            member_type_list.append("%s_refm" % cur_refm.name)
            member_name_list.append("mo_%s_refm" % cur_refm.name)
        for cur_scb in self.scb_list:
            member_type_list.append("%s_scb" % cur_scb.name)
            member_name_list.append("mo_%s_scb" % cur_scb.name)
        aligned_member_type_list = PubFunc.align_list(member_type_list)

        content = '''
`ifndef ENV__SV
`define ENV__SV

class env extends uvm_env;
'''
        for index in range(len(aligned_member_type_list)):
            content += "    %s%s;\n" % (aligned_member_type_list[index], member_name_list[index])

        # field automatic
        content += "\n"
        content += "    `uvm_component_utils_begin(env)\n"
        content += "        `uvm_field_object(mo_vir_seqr, UVM_ALL_ON)\n"
        content += "        `uvm_field_object(mo_regmodel, UVM_ALL_ON)\n"
        content += "        `uvm_field_object(mo_env_cfg, UVM_ALL_ON)\n"
        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip:
                continue
            if cur_agent.count == 1:
                content += "        `uvm_field_object(mo_%s_master_agent, UVM_ALL_ON)\n" % cur_agent.name
            else:
                content += "        `uvm_field_sarray_object(moa_%s_master_agent, UVM_ALL_ON)\n" % cur_agent.name
        for cur_agent in self.slv_agent_list:
            if cur_agent.is_vip:
                continue
            if cur_agent.count == 1:
                content += "        `uvm_field_object(mo_%s_slaver_agent, UVM_ALL_ON)\n" % cur_agent.name
            else:
                content += "        `uvm_field_sarray_object(moa_%s_slaver_agent, UVM_ALL_ON)\n" % cur_agent.name
        for cur_refm in self.refm_list:
            content += "        `uvm_field_object(mo_%s_refm, UVM_ALL_ON)\n" % cur_refm.name
        for cur_scb in self.scb_list:
            content += "        `uvm_field_object(mo_%s_scb, UVM_ALL_ON)\n" % cur_scb.name
        content += "    `uvm_component_utils_end\n"

        content += '''
    function new(string name = "env", uvm_component parent = null);
        super.new(name, parent);
    endfunction : new

    extern virtual function void build_phase(uvm_phase phase);
    extern virtual function void create_agent();
    extern virtual function void create_refm();
    extern virtual function void create_scb();
    extern virtual function void config_regmodel();
    extern virtual function void config_env();

    extern virtual function void connect_phase(uvm_phase phase);

endclass : env

function void env::build_phase(uvm_phase phase);
    super.build_phase(phase);
    // config reg model
    this.config_regmodel();

    // config_env
    this.config_env();

    // virtual sequencer
    this.mo_vir_seqr = vir_seqr::type_id::create("mo_vir_seqr", this);

    // create agent
    this.create_agent();

    // create refm
    this.create_refm();

    // create scoreboard
    this.create_scb();
endfunction : build_phase

function void env::config_env();
    // get env_cfg
    if(!uvm_config_db#(env_cfg)::get(this, "", "mo_env_cfg", this.mo_env_cfg))
    begin
        `uvm_fatal(get_type_name(), "fail get mo_env_cfg!")
    end
'''
        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip == True:
                continue
            if cur_agent.count == 1:
                content += "    uvm_config_db#(%s_agent_cfg)::set(this, \"mo_%s_master_agent.*\", \"mo_agent_cfg\", this.mo_env_cfg.mo_%s_master_agent_cfg);\n" % \
                    (cur_agent.name, cur_agent.name, cur_agent.name)
                continue
            for index in range(cur_agent.count):
                content += "    uvm_config_db#(%s_agent_cfg)::set(this, \"moa_%s_master_agent[%s].*\", \"mo_agent_cfg\", this.mo_env_cfg.moa_%s_master_agent_cfg[%s]);\n" % \
                    (cur_agent.name, cur_agent.name, index, cur_agent.name, index)
        for cur_agent in self.slv_agent_list:
            if cur_agent.is_vip == True:
                continue
            if cur_agent.count == 1:
                content += "    uvm_config_db#(%s_agent_cfg)::set(this, \"mo_%s_slaver_agent.*\", \"mo_agent_cfg\", this.mo_env_cfg.mo_%s_slaver_agent_cfg);\n" % \
                    (cur_agent.name, cur_agent.name, cur_agent.name)
                continue
            for index in range(cur_agent.count):
                content += "    uvm_config_db#(%s_agent_cfg)::set(this, \"moa_%s_slaver_agent[%s].*\", \"mo_agent_cfg\", this.mo_env_cfg.moa_%s_slaver_agent_cfg[%s]);\n" % \
                (cur_agent.name, cur_agent.name, index, cur_agent.name, index)
        content += "\n"
        content += "endfunction : config_env\n"
        content += "\n"
        content += "function void env::create_agent();\n"
        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip:
                continue
            if cur_agent.count == 1:
                content += "    this.mo_%s_master_agent = %s_agent::type_id::create(\"mo_%s_master_agent\", this);\n" % \
                        (cur_agent.name, cur_agent.name, cur_agent.name)
                continue
            for index in range(cur_agent.count):
                content += "    this.moa_%s_master_agent[%s] = %s_agent::type_id::create(\"moa_%s_master_agent[%s]\", this);\n" % \
                        (cur_agent.name, index, cur_agent.name, cur_agent.name, index)
        for cur_agent in self.slv_agent_list:
            if cur_agent.is_vip:
                continue
            if cur_agent.count == 1:
                content += "    this.mo_%s_slaver_agent = %s_agent::type_id::create(\"mo_%s_slaver_agent\", this);\n" % \
                        (cur_agent.name, cur_agent.name, cur_agent.name)
                continue
            for index in range(cur_agent.count):
                content += "    this.moa_%s_slaver_agent[%s] = %s_agent::type_id::create(\"moa_%s_slaver_agent[%s]\", this);\n" % \
                        (cur_agent.name, index, cur_agent.name, cur_agent.name, index)

        content += "endfunction : create_agent\n"
        content += "\n"
        content += "function void env::create_refm();\n"
        for cur_refm in self.refm_list:
            content += "    this.mo_%s_refm = %s_refm::type_id::create(\"mo_%s_refm\", this);\n" % (cur_refm.name, cur_refm.name, cur_refm.name)
        content += "endfunction : create_refm\n"
        content += "\n"
        content += "function void env::create_scb();\n"
        for cur_scb in self.scb_list:
            content += "    this.mo_%s_scb = %s_scb::type_id::create(\"mo_%s_scb\", this);\n" % (cur_scb.name, cur_scb.name, cur_scb.name)
        content += "endfunction : create_scb\n"
        content += "\n"
        content += "function void env::config_regmodel();\n"
        content += "    this.mo_regmodel= ral_regmodel::type_id::create(\"mo_regmodel\", this);\n"
        content += "    this.mo_regmodel.configure(null, "");\n"
        content += "    this.mo_regmodel.build();\n"
        content += "    this.mo_regmodel.lock_model();\n"
        content += "    this.mo_regmodel.reset();\n"
        content += "    \n"
        content += "    uvm_config_db#(ral_regmodel)::set(this, \"*\", \"mo_regmodel\", this.mo_regmodel);\n"
        content += "endfunction : config_regmodel\n"
        content += "\n"
        content += "function void env::connect_phase(uvm_phase phase);\n"
        content += "    this.mo_regmodel.default_map.set_auto_predict(1);\n"
        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip:
                continue
            if cur_agent.count == 1:
                content += "    this.mo_vir_seqr.mo_%s_seqr = this.mo_%s_master_agent.mo_seqr;\n" % \
                        (cur_agent.name, cur_agent.name)
                continue
            for index in range(cur_agent.count):
                content += "    this.mo_vir_seqr.moa_%s_seqr[%s] = this.moa_%s_master_agent[%s].mo_seqr;\n" % \
                        (cur_agent.name, index, cur_agent.name, index)
        content += "endfunction : connect_phase\n"
        content += "\n"
        content += "`endif // ENV__SV\n"
        content += "\n"
        file_handler.write(content)
        file_handler.close()

    def gen_vir_seqr(self):
        member_type_list = []
        member_name_list = []
        aligned_member_type_list = []
        file_name = "vir_seqr.sv"
        file_path = "%s/env/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))

        content = '''
`ifndef VIR_SEQR__SV
`define VIR_SEQR__SV

class vir_seqr extends uvm_sequencer;
'''
        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip:
                continue
            member_type_list.append("%s_seqr" % cur_agent.name)
            if cur_agent.count == 1:
                member_name_list.append("mo_%s_seqr" % cur_agent.name)
                continue
            member_name_list.append("moa_%s_seqr[%s]" % (cur_agent.name, cur_agent.count))
        aligned_member_type_list = PubFunc.align_list(member_type_list)
        for index in range(len(aligned_member_type_list)):
            content += "    %s%s;\n" % (aligned_member_type_list[index], member_name_list[index])

        # field automatic
        content += "\n"
        content += "    `uvm_component_utils_begin(vir_seqr)\n"
        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip:
                continue
            if cur_agent.count == 1:
                content += "        `uvm_field_object(mo_%s_seqr, UVM_ALL_ON)\n" % cur_agent.name
                continue
            content += "        `uvm_field_sarray_object(moa_%s_seqr, UVM_ALL_ON)\n" % cur_agent.name
        content += "    `uvm_component_utils_end\n"
        content += '''
    extern          function            new         (string name = "vir_seqr", uvm_component parent = null);
    extern  virtual function    void    build_phase (uvm_phase phase);

endclass : vir_seqr

function vir_seqr::new(string name = "vir_seqr", uvm_component parent = null);
    super.new(name, parent);
endfunction : new

function void vir_seqr::build_phase(uvm_phase phase);
    super.build_phase(phase);
    `uvm_info("", "This is build_phase", UVM_LOW)\n
'''
        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip:
                continue
            if cur_agent.count == 1:
                content += "    this.mo_%s_seqr = %s_seqr::type_id::create(\"mo_%s_seqr\", this);\n" % \
                        (cur_agent.name, cur_agent.name, cur_agent.name)
                continue
            content += "    foreach(this.moa_%s_seqr[index])\n" % cur_agent.name
            content += "    begin\n"
            content += "        this.moa_%s_seqr[index] = %s_seqr::type_id::create($sformatf(\"moa_%s_seqr[%%0d]\", index), this);\n" % \
                    (cur_agent.name, cur_agent.name, cur_agent.name)
            content += "    end\n"
        content += "endfunction : build_phase\n"
        content += "\n"
        content += "`endif // VIR_SEQR__SV\n\n"

        file_handler.write(content)
        file_handler.close()

    def gen_files(self):
        self.gen_env()
        self.gen_vir_seqr()

#!/usr/bin/env python3

import sys
import os
import re

from operator import attrgetter

cur_scr_dir = os.path.dirname(os.path.abspath(__file__))
pubfunc_dir = os.path.abspath(cur_scr_dir + "/../../public")
sys.path.append(pubfunc_dir)

from pubfunc import PubFunc

class TbFiles:
    def __init__(self, env_gen):
        self.project_path = env_gen.project_path
        self.mst_agent_list = env_gen.mst_agent_list
        self.slv_agent_list = env_gen.slv_agent_list
        self.env_gen = env_gen

    def __str__(self):
        str_info = ""
        str_info += "------ TbFiles Start ------\n"
        str_info += "project_path(%s)\n" % self.project_path
        str_info += "------ TbFiles End ------\n"
        return str_info

    def gen_dummy_file_for_post_sim(self):
        file_name = "dummy_module_for_netlist.sv"
        file_path = "%s/tb/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))
        content = '''
`ifndef DUMMY_MODULE_FOR_NETLIST__SV
`define DUMMY_MODULE_FOR_NETLIST__SV

module XXXX();
endmodule

`endif // DUMMY_MODULE_FOR_NETLIST__SV
'''
        file_handler.write(content)
        file_handler.close()

    def gen_gpio_connection_file(self):
        file_name = "gpio_connection.sv"
        file_path = "%s/tb/sub_connection/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))
        content = '''
`ifndef GPIO_CONNECTION__SV
`define GPIO_CONNECTION__SV

reg     [PA_NUM - 1 : 0]    pa_out;
reg     [PB_NUM - 1 : 0]    pb_out;
reg     [PC_NUM - 1 : 0]    pc_out;
reg     [PD_NUM - 1 : 0]    pd_out;

reg     [PA_NUM - 1 : 0]    pa_out_en;
reg     [PB_NUM - 1 : 0]    pb_out_en;
reg     [PC_NUM - 1 : 0]    pc_out_en;
reg     [PD_NUM - 1 : 0]    pd_out_en;


pullup(PA[0]);
pullup(PA[1]);
pullup(PA[2]);
pullup(PA[3]);

pullup(PB[0]);
pullup(PB[1]);
pullup(PB[2]);
pullup(PB[3]);
pullup(PB[4]);
pullup(PB[5]);
pullup(PB[6]);
pullup(PB[7]);

pullup(PC[0]);

pullup(PD[0]);

// use assign to complete the value action
genvar i;
generate begin
    for(i=0; i<PA_NUM; i++)
    begin
        assign PA[i] = pa_out_en[i] ? pa_out[i] : 1'bz;
    end
end
endgenerate

generate begin
    for(i=0; i<PB_NUM; i++)
    begin
        assign PB[i] = pb_out_en[i] ? pb_out[i] : 1'bz;
    end
end
endgenerate

generate begin
    for(i=0; i<PC_NUM; i++)
    begin
        assign PC[i] = pc_out_en[i] ? pc_out[i] : 1'bz;
    end
end
endgenerate

generate begin
    for(i=0; i<PD_NUM; i++)
    begin
        assign PD[i] = pd_out_en[i] ? pd_out[i] : 1'bz;
    end
end
endgenerate

`endif
'''
        file_handler.write(content)
        file_handler.close()

    def gen_power_control_connection_file(self):
        file_name = "power_control.sv"
        file_path = "%s/tb/sub_connection/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))
        content = '''
`ifndef POWER_CONTROL__SV
`define POWER_CONTROL__SV

// --------------------- power control ----------------- //
event   power_on_event;
event   power_off_event;

initial
begin
    VDD     = 0.0;
    GND     = 0.0;
    #2us;
    ->power_on_event;
end
initial
begin
    fork
        while(1)
        begin
            @power_on_event;
            VDD     = 5.0;
            `uvm_info("","POWER on ....",UVM_LOW)
        end
        while(1)
        begin
            @power_off_event;
            VDD     = 0.0;
            `uvm_info("","POWER off ....",UVM_LOW)
        end
    join
end

`endif // POWER_CONTROL__SV
'''
        file_handler.write(content)
        file_handler.close()

    def gen_top_connection_file(self):
        file_name = "top_connection.sv"
        file_path = "%s/tb/%s" % (self.project_path, file_name)
        file_handler = open(file_path, 'w')
        file_handler.write(PubFunc.get_file_header('//', file_name))
        content = '''
