            # not VIP
            if cur_agent.count == 1:
                content += "        `uvm_field_object(mo_%s_master_agent_cfg, UVM_ALL_ON)\n" % cur_agent.name
            else:
                content += "        `uvm_field_sarray_object(moa_%s_master_agent_cfg, UVM_ALL_ON)\n" % cur_agent.name
        for cur_agent in self.slv_agent_list:
            if cur_agent.is_vip == True:
                # VIP is completed by patch
