            else:
                content += "        `uvm_field_sarray_object(moa_%s_slaver_agent_cfg, UVM_ALL_ON)\n" % cur_agent.name
        content += "    `uvm_object_utils_end\n"

        content += '''
    function new(string name = "env_cfg");
        super.new(name);
    endfunction : new

    extern function void create_env_cfg();
    extern function void modify_env_cfg();

endclass : env_cfg\n
'''
        content += "function void env_cfg::create_env_cfg();\n"
        content += "    // instance master agent cfg\n"
        for cur_agent in self.mst_agent_list:
            if cur_agent.is_vip == True:
