            if cur_agent.count == 1:
                content += "    this.mo_%s_master_agent_cfg = %s_agent_cfg::type_id::create(\"mo_%s_master_agent_cfg\");\n" % \
                    (cur_agent.name, cur_agent.name, cur_agent.name)
            else:
                content += "    foreach(this.moa_%s_master_agent_cfg[index])\n" % cur_agent.name
                content += "    begin\n"
                content += "        this.moa_%s_master_agent_cfg[index] = %s_agent_cfg::type_id::create($sformatf(\"moa_%s_master_agent_cfg[%%0d]\", index));\n" % \
                        (cur_agent.name, cur_agent.name, cur_agent.name)
                content += "    end\n"
        content += "\n"
        content += "    // instance slaver agent cfg\n"
        for cur_agent in self.slv_agent_list:
            if cur_agent.is_vip == True:
                continue
            if cur_agent.count == 1:
                content += "    this.mo_%s_slaver_agent_cfg = %s_agent_cfg::type_id::create(\"mo_%s_slaver_agent_cfg\");\n" % \
                    (cur_agent.name, cur_agent.name, cur_agent.name)
            else:
                content += "    foreach(this.moa_%s_slaver_agent_cfg[index])\n" % cur_agent.name
                content += "    begin\n"
                content += "        this.moa_%s_slaver_agent_cfg[index] = %s_agent_cfg::type_id::create($sformatf(\"moa_%s_slaver_agent_cfg[%%0d]\", index));\n" % \
                        (cur_agent.name, cur_agent.name, cur_agent.name)
                content += "    end\n"
        content += "endfunction : create_env_cfg\n\n"

        content += "function void env_cfg::modify_env_cfg();\n"
        for cur_agent in self.mst_agent_list:
