            content += "    // mo_%s_master_agent_cfg\n" % cur_agent.name
            if cur_agent.count == 1:
                content += "    this.mo_%s_master_agent_cfg.is_active = UVM_ACTIVE;\n" % cur_agent.name
            else:
                for index in range(cur_agent.count):
                    content += "    this.moa_%s_master_agent_cfg[%s].is_active = UVM_ACTIVE;\n" % (cur_agent.name, index)
            content += "\n"

        for cur_agent in self.slv_agent_list:
            if cur_agent.is_vip == True:
                continue
            content += "    // mo_%s_slaver_agent_cfg\n" % cur_agent.name
            if cur_agent.count == 1:
                content += "    this.mo_%s_slaver_agent_cfg.is_active = UVM_PASSIVE;\n" % cur_agent.name
            else:
                for index in range(cur_agent.count):
                    content += "    this.moa_%s_slaver_agent_cfg[%s].is_active = UVM_PASSIVE;\n" % (cur_agent.name, index)
            content += "\n"
        content += "endfunction : modify_env_cfg\n\n"
        content += "`endif // ENV_CFG__SV\n\n"
        file_handler.write(content)
        file_handler.close()

