            VDD     = 5.0;
            `uvm_info("","POWER on ....",UVM_LOW)
        end
        while(1)
        begin
            @power_off_event;
            VDD     = 0.0;
            `uvm_info("","POWER off ....",UVM_LOW)
        end
    join
end

