#!/usr/bin/env python3

import sys
import os
import re
import datetime
import time
import getpass
import subprocess
import glob

class PubFunc:
    def print_err(err_info):
        print("\033[1;31mUVM_ERROR @ 0ps:  [] : %s\033[0m" % err_info)

    def print_warn(warn_info):
        print("\033[1;31m[WARNING] %s\033[0m" % warn_info)

    def exit_err(err_info):
        sys.exit("\033[1;31mUVM_ERROR @ 0ps:  [] : %s\033[0m" % err_info)

    def get_file_header(comment_symbol, file_name):
        comm_header = ""
        comm_header += "%s ----------------------------------------------------\n" % comment_symbol
        comm_header += "%s Copyright(C) %d Chipsea All rights reserved.\n" % (comment_symbol, datetime.datetime.now().year)
        comm_header += "%s File Name: %s\n" % (comment_symbol, file_name)
        comm_header += "%s Author:    %s\n" % (comment_symbol, getpass.getuser())
        comm_header += "%s Email:     %s@chipsea.com\n" % (comment_symbol, getpass.getuser())
        comm_header += "%s Date:      %s\n" % (comment_symbol, datetime.date.today())
        comm_header += "%s ----------------------------------------------------\n" % comment_symbol
        return comm_header

    def get_indents(indent_num):
        return "    "*indent_num

    def rm_item_in_list(src_list, item):
        dst_list = []
        for cur_item in src_list:
            if cur_item != item:
                dst_list.append(cur_item)
        return dst_list

    def sort_list_by_attr(src_list, attr, is_reverse):
        dst_list = sorted(src_list, key=attrgetter(attr), reverse=is_reverse)
        return dst_list

    def get_dir_flist(cur_dir):
        cur_flist = []
        for root, dirs, files in os.walk(cur_dir):
            for cur_file in files:
                cur_flist.append(os.path.join(root, cur_file))
        return cur_flist

    def rpt_xlsx_row_err(sheetname, row, err_info):
        PubFunc.print_err("sheet(%s), row(%d): %s" % (sheetname, row, err_info))

    def rpt_xlsx_cell_err(sheetname, row, col, err_info):
        PubFunc.print_err("sheet(%s), row(%d), col(%d): %s" % (sheetname, row, col, err_info))

    def match_1_word(cur_string):
        matchObj = re.match(r'^\s*(\w+)\s*$', cur_string)
        if matchObj:
            return True, matchObj.group(1)
        else:
            return False, ""

    def match_1_num(cur_string):
        matchObj = re.match(r'^\s*(\d+)\s*$', cur_string)
        if matchObj:
            return True, int(matchObj.group(1))
        else:
            return False, -1

    def align_list(list = []):
        max_char_num = 0
        target_list = []
        for index in list:
            if len(index) > max_char_num:
                max_char_num = len(index)
        max_char_num = 4 - (max_char_num % 4) + max_char_num + 4 * 1

        for index in range(len(list)):
            temp_item = list[index]
            for space_index in range(max_char_num - len(list[index])):
                temp_item = temp_item + ' '
            target_list.append(temp_item)
        return target_list

    def append_content_to_file(content_list, target_file, target_line_num):
        if target_line_num < -1:
            PubFunc:print_err("%s : target_line_num is %0s" % (target_file, target_line_num))
            return

        if os.path.isfile(target_file) == False:
            parent_path = os.path.dirname(target_file)
            if not os.path.exists(parent_path):
                os.makedirs(parent_path)
            file_handler = open(target_file, 'w')
            for index in range(target_line_num):
                file_handler.write("\n")

